const paisItems = $input.all();
const TIER12 = paisItems.filter(p => p.json.tier <= 2).map(p => p.json.pais);

const queryLines = [];
for (const pais of TIER12) {
  queryLines.push('finanzas emprendedores ' + pais + ' site:tiktok.com/@');
  queryLines.push('tecnologia negocios ' + pais + ' site:tiktok.com/@');
}

return [{ json: { queries: queryLines.join('\n') } }];

const paisItems = $('Config países').all();

function parseViews(str) {
  if (!str) return 0;
  // "Más de 1,3 M visualizaciones" / "Más de 29.7 K vistas" / "Más de 620 visualizaciones"
  const m = str.match(/([\d.,]+)\s*([MK])?/i);
  if (!m) return 0;
  const num = parseFloat(m[1].replace(',', '.'));
  const mult = (m[2] || '').toUpperCase() === 'M' ? 1000000 : (m[2] || '').toUpperCase() === 'K' ? 1000 : 1;
  return Math.round(num * mult);
}

const creadores = new Map(); // handle → datos agregados

for (const inp of $input.all()) {
  const queryTerm = (inp.json.searchQuery?.term || '').toLowerCase();
  const results = inp.json.organicResults || [];

  let paisDetectado = 'LATAM';
  let tierDetectado = 2;
  for (const p of paisItems) {
    if (queryTerm.includes(p.json.pais.toLowerCase())) {
      paisDetectado = p.json.pais;
      tierDetectado = p.json.tier;
      break;
    }
  }

  for (const r of results) {
    const url = r.url || '';
    // Handle desde cualquier URL de TikTok: /@handle o /@handle/video/123
    const m = url.match(/tiktok\.com\/@([a-zA-Z0-9._]+)/);
    if (!m) continue;
    const handle = m[1].toLowerCase();

    // Nombre del creador: websiteTitle "TikTok · Nombre" es lo más confiable
    let nombre = '';
    const wt = r.websiteTitle || '';
    if (wt.includes('·')) nombre = wt.split('·').pop().trim();
    if (!nombre || nombre.toLowerCase() === 'tiktok') nombre = handle;

    const views = parseViews(r.views || '');
    const desc = r.description || '';

    if (!creadores.has(handle)) {
      creadores.set(handle, {
        handle, nombre, pais: paisDetectado, tier: tierDetectado,
        videos: 0, maxViews: 0, bio: desc.substring(0, 300)
      });
    }
    const c = creadores.get(handle);
    c.videos++;
    if (views > c.maxViews) c.maxViews = views;
    // Preferir nombre real sobre handle
    if (c.nombre === c.handle && nombre !== handle) c.nombre = nombre;
  }
}

const out = [];
for (const [, c] of creadores) {
  out.push({ json: {
    tipo: 'TikTok',
    nombre: c.nombre,
    show: '@' + c.handle,
    medio: 'TikTok',
    pais: c.pais,
    tier: c.tier,
    website: 'https://www.tiktok.com/@' + c.handle,
    rss: '',
    genero: 'Creador finanzas/tech',
    episodios: 0,
    seguidores: c.maxViews,
    email: '',
    bio: c.bio,
    notas_origen: 'TikTok - ' + c.pais + ' - @' + c.handle + ' - ' + (c.maxViews > 0 ? c.maxViews.toLocaleString() + ' views max' : 'sin datos de views') + ' - ' + c.videos + ' videos en resultados'
  }});
}

// Más views primero
out.sort((a, b) => (b.json.seguidores || 0) - (a.json.seguidores || 0));
return out;

