function getMedioFromUrl(url) {
  const hostname = getHostname(url);
  if (!hostname) return null;
  let best = null, bestLen = 0;
  for (const [domain, data] of Object.entries(DOMINIO_A_MEDIO)) {
    if ((hostname === domain || hostname.endsWith('.' + domain)) && domain.length > bestLen) {
      best = data; bestLen = domain.length;
    }
  }
  return best;
}

const SKIP_AUTOR = new Set(['staff','redacción','redaccion','admin','editor','equipo','team','np','n/a','agencia','reuters','efe','ap','afp']);
const hace90 = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000);

const TECH_KW = [
  'ai','ia','inteligencia artificial','machine learning','llm','gpt','openai','chatgpt',
  'tech','tecnolog','software','startup','app','digital','cloud','data','cyber','hack',
  'robot','automat','bitcoin','crypto','blockchain','fintech','saas','api','developer',
  'programac','código','algoritmo','silicon','venture','ronda de','unicornio',
  'ecommerce','e-commerce','marketplace','plataforma','streaming','contabilidad','facturación',
  'iphone','android','google','apple','meta','microsoft','amazon','nvidia','tesla',
  'intel','samsung','xiaomi','drone','5g','semiconductor','chip','computadora',
  'laptop','smartphone','wearable','iot','internet of things','electric vehicle',
  'vehículo eléctrico','ciberseguridad','seguridad inform','privacidad digital',
  'inversión','financiamiento','levantamiento','capital','vc','emprendimiento','pyme','sme',
  'negocios digitales','transformación digital','economía digital','impuestos','fiscal','tributari'
];

const MEDIOS_MIXTOS = new Set([
  'Wired','MIT Tech Review','The Verge','El País Tech','Prensa Libre','El Deber',
  'La Prensa Gráfica','El Faro','ABC Color','El Nuevo Día','La Prensa PA','CRHoy',
  'El País Uruguay','Primicias','El Tiempo Economía','La Tercera','El Confidencial'
]);

const out = [];
for (const inp of $input.all()) {
  const item = inp.json;
  if (item.error) continue;

  const titulo = (item.title || '').trim();
  const url    = item.link || item.guid || '';
  if (!titulo || !url) continue;

  const medioData = getMedioFromUrl(url);
  if (!medioData) continue;

  const { medio, pais, idioma, tier } = medioData;

  if (MEDIOS_MIXTOS.has(medio)) {
    const textoLow = (titulo + ' ' + (item.contentSnippet || '')).toLowerCase();
    if (!TECH_KW.some(k => textoLow.includes(k))) continue;
  }

  const autorRaw = (
    item['dc:creator'] || item.creator || item.author || item['itunes:author'] || ''
  ).replace(/<[^>]*>/g, '').trim();
  const autorFinal = autorRaw.length > 2 && !SKIP_AUTOR.has(autorRaw.toLowerCase()) ? autorRaw : '';

  const fechaStr = item.isoDate || item.pubDate || '';
  const fecha    = fechaStr ? new Date(fechaStr) : new Date();
  if (!isNaN(fecha.getTime()) && fecha < hace90) continue;
  const fechaISO = !isNaN(fecha.getTime()) ? fecha.toISOString().split('T')[0] : new Date().toISOString().split('T')[0];

  out.push({ json: {
    autor: autorFinal,
    medio, pais, idioma, tier,
    titulo, url, fecha: fechaISO,
    snippet: (item.contentSnippet || item['content:encodedSnippet'] || '').replace(/<[^>]*>/g, '').substring(0, 250)
  } });
